
import re
from pathlib import Path


# Linux authentication log format generated by our log generator.
AUTH_PATTERN = re.compile(
    r"^(L\d{4})\s+"
    r"([A-Z][a-z]{2}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2})\s+"
    r"(\S+)\s+"
    r"(.*)$"
)

# Apache access log format generated by our log generator.
APACHE_PATTERN = re.compile(
    r'^(L\d{4})\s+'
    r'(\S+)\s+-\s+-\s+'
    r'\[([^\]]+)\]\s+'
    r'"(\S+)\s+(.+?)\s+HTTP/[\d.]+"\s+'
    r'(\d{3})\s+(\d+)\s+'
    r'"([^"]*)"\s+"([^"]*)"'
)


def parse_auth_line(line):
    """Parse one Linux authentication log entry."""
    match = AUTH_PATTERN.match(line.strip())

    if not match:
        return None

    line_id, timestamp, host, message = match.groups()

    event_type = "other"

    if "Failed password" in message:
        event_type = "failed_login"
    elif (
        "Accepted password" in message
        or "Accepted publickey" in message
    ):
        event_type = "successful_login"
    elif "sudo" in message.lower():
        event_type = "sudo_activity"
    elif "CRON" in message:
        event_type = "scheduled_task"

    # Extract an IP address if one exists in the message.
    ip_match = re.search(
        r"\b(?:10\.\d{1,3}\.\d{1,3}\.\d{1,3})\b",
        message,
    )

    # Extract a username from SSH login messages.
    user_match = re.search(
        r"(?:Failed password for (?:invalid user )?|"
        r"Accepted (?:password|publickey) for )"
        r"([a-zA-Z0-9_.-]+)",
        message,
    )

    return {
        "line_id": line_id,
        "log_type": "auth",
        "timestamp": timestamp,
        "host": host,
        "ip": ip_match.group(0) if ip_match else None,
        "user": user_match.group(1) if user_match else None,
        "event_type": event_type,
        "message": message,
        "raw": line.strip(),
    }


def parse_apache_line(line):
    """Parse one Apache access log entry."""
    match = APACHE_PATTERN.match(line.strip())

    if not match:
        return None

    (
        line_id,
        ip,
        timestamp,
        method,
        path,
        status,
        size,
        referrer,
        user_agent,
    ) = match.groups()

    return {
        "line_id": line_id,
        "log_type": "apache",
        "timestamp": timestamp,
        "ip": ip,
        "method": method,
        "path": path,
        "status": int(status),
        "size_bytes": int(size),
        "referrer": referrer,
        "user_agent": user_agent,
        "event_type": "web_request",
        "raw": line.strip(),
    }


def parse_file(file_path, parser):
    """Parse every non-empty line in a file."""
    records = []
    errors = []

    with open(file_path, "r", encoding="utf-8") as file:
        for line_number, line in enumerate(file, start=1):
            if not line.strip():
                continue

            record = parser(line)

            if record is None:
                errors.append({
                    "file_line": line_number,
                    "content": line.rstrip(),
                })
            else:
                records.append(record)

    return records, errors


def parse_scenario(scenario_dir):
    """Parse both log files in a scenario directory."""
    scenario_dir = Path(scenario_dir)

    all_records = []
    all_errors = []

    files = [
        ("auth.log", parse_auth_line),
        ("access.log", parse_apache_line),
    ]

    for filename, parser in files:
        file_path = scenario_dir / filename

        # An empty or missing log file is allowed.
        if not file_path.exists():
            continue

        records, errors = parse_file(file_path, parser)

        all_records.extend(records)

        for error in errors:
            error["file"] = filename
            all_errors.append(error)

    return all_records, all_errors


if __name__ == "__main__":
    project_dir = Path(__file__).resolve().parent.parent
    data_dir = project_dir / "data"

    for scenario_dir in sorted(data_dir.glob("S*")):
        if not scenario_dir.is_dir():
            continue

        records, errors = parse_scenario(scenario_dir)

        print(f"\n{scenario_dir.name}")
        print(f"Parsed records: {len(records)}")
        print(f"Parse errors: {len(errors)}")

        if records:
            print("First parsed record:")
            print(records[0])

        if errors:
            print("First parse error:")
            print(errors[0])
